        const f16v q2 = __builtin_convertvector(qi << 16 >> 28, f16v);
        const f16v qs = 1.5f * ((q0 + q1) + q2);
        const f16v sc = (f16v) ((u16v) (m->bias + 16 + 127) + (q & 15u) << 23) * NSLM_R32;
